// Shared by the scene and scripts/bakeMeteor.mjs, so the bake verifies exactly what plays.
// BAKE is written by: node --experimental-strip-types scripts/bakeMeteor.mjs

export const SIZE = 0.75
export const CELL = 0.77
export const PITCH = 0.86
export const COLUMNS = 13
export const ROWS = 5
export const COUNT = COLUMNS * ROWS
export const METEOR = COUNT - 1
export const METEOR_SLOT = { column: 8, row: 1 }

export const SIM_YAW = 0.68
export const SIM_FPS = 40
export const FLOOR = -4.5
export const TRAY_X = -0.9
export const TRAY_Z = 0.2
export const RIM_HEIGHT = 0.96
export const RIM_WIDTH = COLUMNS * PITCH + 0.1
export const RIM_DEPTH = ROWS * PITCH + 0.1
export const RIM_LAND = 0.7

// The meteor strikes the right front face, travelling slightly upwards.
export const STRIKE_SPEED = 26
export const STRIKE_DIR: Vec = [-0.71, 0.2, -0.67]
export const STRIKE_START: Vec = [1.25, -0.245, 1.49]
export const IMPACT_POINT: Vec = [0.95, -0.2, 1.2]

export const FOV_SCALE = 2 * Math.tan((14 * Math.PI) / 180)
export const START_LOOK = 0.5
export const LONE_STAR = { x: 0.32, y: 0.62, depth: 62 }

export const INTRO_ARRIVE = 3.4
export const INTRO_SPREAD = 1.7
const INTRO_PACE = 2
const NEAR = 0.6
export const INTRO_TIME = INTRO_ARRIVE + INTRO_SPREAD + 0.35

export type Vec = [number, number, number]
export type Pose = { x: number; y: number; z: number; qx: number; qy: number; qz: number; qw: number; scale: number; heat: number; sky: number }

export const clamp = (x: number, min = 0, max = 1) => Math.min(max, Math.max(min, x))
export const smooth = (a: number, b: number, x: number) => {
  const t = clamp((x - a) / (b - a))
  return t * t * (3 - 2 * t)
}

let seed = 11
const random = () => {
  seed = (seed * 16807) % 2147483647
  return seed / 2147483647
}

export const cells: Vec[] = []
for (let x = 0; x < 4; x++) {
  for (let y = 0; y < 4; y++) {
    for (let z = 0; z < 4; z++) cells.push([(x - 1.5) * CELL, (y - 1.5) * CELL, (z - 1.5) * CELL])
  }
}

export const slotAt = (column: number, row: number): Vec => [
  TRAY_X + (column - (COLUMNS - 1) / 2) * PITCH,
  FLOOR + SIZE / 2,
  TRAY_Z + (row - (ROWS - 1) / 2) * PITCH,
]

// Sorted by radius: a cube riding its ray outwards only ever moves away from cells nearer the centre.
const order = cells
  .map((cell, i) => ({ i, radius: Math.round(Math.hypot(...cell) * 100), turn: Math.atan2(cell[2], cell[0]) + cell[1] * 0.4 }))
  .sort((a, b) => a.radius - b.radius || a.turn - b.turn)
const rank = new Float32Array(cells.length)
order.forEach(({ i }, position) => (rank[i] = position / (cells.length - 1)))

const spins = cells.map(() => {
  const x = random() - 0.5
  const y = random() - 0.5
  const z = random() - 0.5
  const length = Math.hypot(x, y, z)
  return { x: x / length, y: y / length, z: z / length, turns: 2 + random() * 3 }
})

// Every star holds still for a beat at the start, then leaves on its own schedule.
const paces = cells.map(() => 1.75 + random() * 0.6)

const skies = cells.map(() => {
  let x = 0
  let y = 0
  do {
    x = random() * 1.92 - 0.96
    y = random() * 1.84 - 0.92
  } while (Math.abs(x) < 0.4 && Math.abs(y) < 0.62)
  return { x, y, depth: 62 + random() * 60 }
})

// In the box's own frame. Each cube rides a straight ray out of its cell, and that ray is twisted,
// which swirls the flight without ever crossing two paths. `sky` is how far it still is from
// its resting star: both ends are on screen, so the mix of them is too.
export function introPose(i: number, time: number, out: Pose) {
  const arrive = INTRO_ARRIVE + rank[i] * INTRO_SPREAD
  // Speeds differ in the sky but share one pace near the box, which keeps arrival order safe.
  const left = arrive - time
  const rest = clamp(left < NEAR ? left / INTRO_PACE : NEAR / INTRO_PACE + ((left - NEAR) * (1 - NEAR / INTRO_PACE)) / (paces[i] - NEAR))
  const u = 1 - rest
  const reach = Math.pow(rest, 2.2)
  const after = time - arrive
  const settle = after > 0 ? 0.045 * Math.exp(-after * 8) * Math.abs(Math.sin(after * 15)) : 0
  const scale = 1 + 7 * reach + settle
  const twist = 2.8 * Math.pow(reach, 0.9)
  const cell = cells[i]
  const cos = Math.cos(twist)
  const sin = Math.sin(twist)
  out.x = (cell[0] * cos - cell[2] * sin) * scale
  out.y = cell[1] * scale + 3 * Math.sin(reach * 5) * reach
  out.z = (cell[0] * sin + cell[2] * cos) * scale
  const spin = spins[i]
  const angle = spin.turns * rest * rest * rest * 3
  const s = Math.sin(angle / 2)
  out.qx = spin.x * s
  out.qy = spin.y * s
  out.qz = spin.z * s
  out.qw = Math.cos(angle / 2)
  out.scale = SIZE * smooth(0.8, 0.975, u)
  out.heat = u <= 0 ? 0 : 1 - smooth(0.8, 0.94, u)
  out.sky = Math.pow(rest, 4.6)
  return u
}

export const OUTLINE_SIZE = 3.48

// Idle life of the frame: layered slow sines, never a single loop.
// Offsets are in world units, in the frame's own axes.
export function frameBreath(time: number, offsets: Float32Array) {
  const wave = (a: number, b: number, c: number) => Math.sin(time * a + c) * 0.62 + Math.sin(time * b + c * 2.3) * 0.38
  for (let i = 0; i < 8; i++) {
    offsets[i * 3] = 0.11 * wave(0.31 + i * 0.013, 0.73, i * 1.7)
    offsets[i * 3 + 1] = 0.11 * wave(0.27 + i * 0.017, 0.61, i * 2.9 + 1)
    offsets[i * 3 + 2] = 0.11 * wave(0.35 - i * 0.011, 0.83, i * 4.3 + 2)
  }
  return 1.09 + 0.06 * wave(0.37, 0.89, 0.4)
}

export const startDistance = (aspect: number) => Math.max(14.6, 5.5 / (0.66 * FOV_SCALE * Math.min(aspect, 1)))

// A point fixed to the screen of the opening shot, at any aspect ratio.
function skyPoint(x: number, y: number, depth: number, aspect: number, out: Vec) {
  const distance = startDistance(aspect)
  const across = x * (FOV_SCALE / 2) * aspect * depth
  const rise = y * (FOV_SCALE / 2) * depth
  out[0] = across
  out[1] = Math.sin(START_LOOK) * (distance - depth) + rise * Math.cos(START_LOOK)
  out[2] = Math.cos(START_LOOK) * (distance - depth) - rise * Math.sin(START_LOOK)
  return out
}

export const loneStar = (aspect: number, out: Vec) => skyPoint(LONE_STAR.x, LONE_STAR.y, LONE_STAR.depth, aspect, out)
export const skyStar = (i: number, aspect: number, out: Vec) => skyPoint(skies[i].x, skies[i].y, skies[i].depth, aspect, out)

// Cubic bezier from the lone star to the strike. Far handle swings wide of the box, near handle
// lines up with the strike direction so the sim picks the velocity up without a kink.
export const meteorHandles = (start: Vec) => ({
  far: start.map((value, k) => value + [34, -14, 26][k]) as Vec,
  near: STRIKE_START.map((value, k) => value - STRIKE_DIR[k] * 11) as Vec,
})

export function meteorPoint(u: number, start: Vec, out: Vec) {
  const { far, near } = meteorHandles(start)
  const a = (1 - u) * (1 - u) * (1 - u)
  const b = 3 * (1 - u) * (1 - u) * u
  const c = 3 * (1 - u) * u * u
  const d = u * u * u
  for (let k = 0; k < 3; k++) {
    out[k] = a * start[k] + b * far[k] + c * near[k] + d * STRIKE_START[k]
  }
  return out
}

